// Lab 18.1, provided (you do not edit this file): the Metal host loops for ref_bfs_push,
// ref_bfs_frontier and bfs_floor, the counterparts of launchRefBfsPush, launchRefBfsFrontier and
// launchBfsFloor in ref_kernels.cu. Each level is its own command buffer: encode one dispatch,
// commit, wait, read what the GPU wrote, decide. Buffers use shared storage (the lab runtime's
// choice), so the CPU writes the root and zeroes the counter directly between command buffers.
// Dispatches on one MTLCommandQueue with default (tracked) buffers run in order and see each
// other's writes (notes/today/ch18-facts.md C2).
#import <Metal/Metal.h>
#include <algorithm>
#include <cstdint>
#include <string>
#include <utility>

#ifndef BLOCK_DIM
#define BLOCK_DIM 128
#endif

// Commits, waits, and returns false (with a message) if the GPU reported an error.
static bool refSubmit(id<MTLCommandBuffer> cb, std::string* error) {
    [cb commit];
    [cb waitUntilCompleted];
    if (cb.status == MTLCommandBufferStatusError) {
        if (error && error->empty())
            *error = std::string("command buffer error: ") +
                     (cb.error ? cb.error.localizedDescription.UTF8String : "unknown");
        return false;
    }
    return true;
}

unsigned int launchRefBfsPush(id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline,
                              id<MTLBuffer> srcPtrs, id<MTLBuffer> dst, uint32_t numVertices,
                              id<MTLBuffer> level, id<MTLBuffer> newVertexVisited, std::string* error) {
    NSUInteger threads = std::min<NSUInteger>(BLOCK_DIM, pipeline.maxTotalThreadsPerThreadgroup);
    NSUInteger groups = (numVertices + threads - 1) / threads;
    unsigned int launches = 0;
    for (uint32_t currLevel = 1; currLevel <= numVertices; ++currLevel) {
        *(uint32_t*)newVertexVisited.contents = 0;
        @autoreleasepool {
            id<MTLCommandBuffer> cb = [queue commandBuffer];
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:pipeline];
            [enc setBuffer:srcPtrs offset:0 atIndex:0];
            [enc setBuffer:dst offset:0 atIndex:1];
            [enc setBytes:&numVertices length:sizeof(uint32_t) atIndex:2];
            [enc setBuffer:level offset:0 atIndex:3];
            [enc setBuffer:newVertexVisited offset:0 atIndex:4];
            [enc setBytes:&currLevel length:sizeof(uint32_t) atIndex:5];
            [enc dispatchThreadgroups:MTLSizeMake(groups, 1, 1) threadsPerThreadgroup:MTLSizeMake(threads, 1, 1)];
            [enc endEncoding];
            ++launches;
            if (!refSubmit(cb, error)) return launches;
        }
        if (*(const uint32_t*)newVertexVisited.contents == 0) break;
    }
    return launches;
}

unsigned int launchRefBfsFrontier(id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline,
                                  id<MTLBuffer> srcPtrs, id<MTLBuffer> dst, uint32_t numVertices, uint32_t root,
                                  id<MTLBuffer> level, id<MTLBuffer> frontierA, id<MTLBuffer> frontierB,
                                  id<MTLBuffer> numCurrFrontier, uint32_t* frontierSizes, std::string* error) {
    id<MTLBuffer> prevFrontier = frontierA;
    id<MTLBuffer> currFrontier = frontierB;
    ((uint32_t*)prevFrontier.contents)[0] = root;
    uint32_t numPrevFrontier = 1;
    if (frontierSizes) frontierSizes[0] = 1;
    NSUInteger threads = std::min<NSUInteger>(BLOCK_DIM, pipeline.maxTotalThreadsPerThreadgroup);
    unsigned int launches = 0;
    for (uint32_t currLevel = 1; numPrevFrontier > 0; ++currLevel) {
        *(uint32_t*)numCurrFrontier.contents = 0;
        @autoreleasepool {
            id<MTLCommandBuffer> cb = [queue commandBuffer];
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:pipeline];
            [enc setBuffer:srcPtrs offset:0 atIndex:0];
            [enc setBuffer:dst offset:0 atIndex:1];
            [enc setBuffer:level offset:0 atIndex:2];
            [enc setBuffer:prevFrontier offset:0 atIndex:3];
            [enc setBuffer:currFrontier offset:0 atIndex:4];
            [enc setBytes:&numPrevFrontier length:sizeof(uint32_t) atIndex:5];
            [enc setBuffer:numCurrFrontier offset:0 atIndex:6];
            [enc setBytes:&currLevel length:sizeof(uint32_t) atIndex:7];
            [enc dispatchThreadgroups:MTLSizeMake((numPrevFrontier + threads - 1) / threads, 1, 1)
                threadsPerThreadgroup:MTLSizeMake(threads, 1, 1)];
            [enc endEncoding];
            ++launches;
            if (!refSubmit(cb, error)) return launches;
        }
        uint32_t numCurr = *(const uint32_t*)numCurrFrontier.contents;
        if (frontierSizes) frontierSizes[currLevel] = numCurr;
        if (numCurr > numVertices || currLevel >= numVertices) break;   // impossible for a correct kernel
        numPrevFrontier = numCurr;
        std::swap(prevFrontier, currFrontier);
    }
    return launches;
}

// The fixed cost of `launches` levels: per level, the counter is zeroed, an empty dispatch is
// committed and waited for, and the count is read, exactly as the frontier searches do.
void launchBfsFloor(id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline, uint32_t launches,
                    id<MTLBuffer> numCurrFrontier, std::string* error) {
    NSUInteger threads = std::min<NSUInteger>(BLOCK_DIM, pipeline.maxTotalThreadsPerThreadgroup);
    volatile uint32_t sink = 0;
    for (uint32_t l = 0; l < launches; ++l) {
        *(uint32_t*)numCurrFrontier.contents = 0;
        @autoreleasepool {
            id<MTLCommandBuffer> cb = [queue commandBuffer];
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            [enc setComputePipelineState:pipeline];
            [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(threads, 1, 1)];
            [enc endEncoding];
            if (!refSubmit(cb, error)) return;
        }
        sink = *(const uint32_t*)numCurrFrontier.contents;
    }
    (void)sink;
}
